// ===== Keystone shared library (generated from ops/lib; do not edit here) =====
const __KS = (() => {
  const defs = {
  'registry': function (module, exports, require) {
'use strict';
// Client Registry: turns a "My Clients" Airtable row into one config object,
// and decides whether a given service may run for that client.
// Rule: every workflow calls gate() first and exits cleanly if it isn't ok.

// Resend's test sender only delivers to the Resend account owner, so demo mail goes here.
const TEST_INBOX = 'khan.bilalbk408@gmail.com';

const SERVICE_TOGGLES = {
  invoicing: 'Invoicing on',
  phone: 'Phone on',
  quotes: 'Quotes on',
  reporting: 'Reporting on',
  monitoring: 'Monitoring on',
};

// Jurisdictions where the phone agent must NOT be deployed (proactive AI disclosure required).
const BLOCKED_PHONE_JURISDICTIONS = ['Republic of Ireland / EU'];

function parseJson(value, fallback) {
  if (value === undefined || value === null || value === '') return fallback;
  if (typeof value === 'object') return value;
  try { return JSON.parse(value); } catch (e) { return { __invalid: true, raw: String(value) }; }
}

function splitList(value) {
  if (!value) return [];
  return String(value).split(/[,;\n]/).map((s) => s.trim()).filter(Boolean);
}

// Accepts an Airtable record ({id, fields}) or a flattened n8n Airtable item.
function normalizeClient(record) {
  const f = record && record.fields ? record.fields : record || {};
  const services = parseJson(f['Services'], []);
  const hours = parseJson(f['Opening hours'], {});
  const pricing = parseJson(f['Pricing rules'], null);
  return {
    recordId: record.id || f.id || null,
    clientId: (f['Client ID'] || '').trim(),
    clientName: f['Client name'] || '',
    status: (f['Status'] && f['Status'].name) || f['Status'] || 'Onboarding',
    isDemo: !!f['Is demo/test'],
    contactName: f['Contact name'] || '',
    contactEmail: f['Contact email'] || '',
    contactPhone: f['Contact phone'] || '',
    industry: f['Industry'] || '',
    halalPassed: !!f['Halal screen passed'],
    jurisdiction: (f['Jurisdiction'] && f['Jurisdiction'].name) || f['Jurisdiction'] || '',
    aiDisclosurePassed: !!f['AI disclosure check passed'],
    toggles: {
      invoicing: !!f['Invoicing on'],
      phone: !!f['Phone on'],
      quotes: !!f['Quotes on'],
      reporting: !!f['Reporting on'],
      monitoring: !!f['Monitoring on'],
    },
    businessEmail: f['Business email'] || f['Contact email'] || '',
    timezone: f['Timezone'] || 'Europe/London',
    invoice: {
      brandLogoUrl: f['Brand logo URL'] || '',
      brandColour: f['Brand colour'] || '#1F3A5F',
      paymentOptions: f['Payment options'] || '',
      sendWindowStart: f['Send window start'] || '',
      sendWindowEnd: f['Send window end'] || '',
      milestoneInvoicingEnabled: !!f['Milestone invoicing enabled'],
      invoiceLineAmountType: (f['Invoice line amount type'] && f['Invoice line amount type'].name) || f['Invoice line amount type'] || 'Inclusive',
      vatRatePct: f['VAT rate %'] === undefined || f['VAT rate %'] === null ? 20 : Number(f['VAT rate %']),
      accountCode: f['Xero account code'] || '200',
      paymentTermsDays: f['Payment terms days'] === undefined || f['Payment terms days'] === null ? 14 : Number(f['Payment terms days']),
      xeroCredentialName: f['Xero credential name'] || '',
      xeroTenantId: f['Xero organisation ID'] || '',
      jobSource: (f['Job source'] && f['Job source'].name) || f['Job source'] || 'Airtable Jobs table',
    },
    phone: {
      businessNumber: normalizePhone(f['Business phone number']),
      receptionNumber: normalizePhone(f['Reception forwarding number']),
      calendarId: f['Calendar ID'] || '',
      services: Array.isArray(services) ? services : [],
      openingHours: hours && !hours.__invalid ? hours : {},
      greeting: f['Greeting'] || '',
      tone: f['Tone / brand voice'] || 'Warm, professional and concise.',
      urgentKeywords: splitList(f['Urgent keywords']),
      escalationSms: normalizePhone(f['Escalation SMS number'] || f['Reception forwarding number']),
    },
    quotes: {
      pricingRules: pricing,
      pricesIncludeVat: !!f['Prices include VAT'],
      validDays: Number(f['Quote valid days']) || 30,
      minMarginPct: f['Minimum margin %'] === undefined || f['Minimum margin %'] === null ? 30 : Number(f['Minimum margin %']),
      approverEmail: f['Quote approver email'] || f['Business email'] || f['Contact email'] || '',
    },
    reporting: { recipients: splitList(f['Report recipients']) },
    dashboardToken: f['Dashboard token'] || '',
    monthlyFee: f['Monthly fee'] || 0,
    prospectIds: f['Prospect'] || [],
    _invalidJson: [
      services && services.__invalid ? 'Services' : null,
      hours && hours.__invalid ? 'Opening hours' : null,
      pricing && pricing.__invalid ? 'Pricing rules' : null,
    ].filter(Boolean),
  };
}

function normalizePhone(p) {
  if (!p) return '';
  let s = String(p).replace(/[^\d+]/g, '');
  if (s.startsWith('00')) s = '+' + s.slice(2);
  if (s.startsWith('0')) s = '+44' + s.slice(1);
  if (!s.startsWith('+') && s.length >= 10) s = '+' + s;
  return s;
}

// The gate. Returns {ok:true} or {ok:false, reason}. Never throws.
function gate(client, service) {
  if (!client || !client.clientId) return { ok: false, reason: 'client_not_found' };
  if (client.status !== 'Active') return { ok: false, reason: `status_${String(client.status).toLowerCase()}` };
  if (!client.halalPassed) return { ok: false, reason: 'halal_screen_not_passed' };
  if (service && SERVICE_TOGGLES[service] && !client.toggles[service]) return { ok: false, reason: `${service}_toggle_off` };
  if (service === 'phone') {
    if (!client.aiDisclosurePassed) return { ok: false, reason: 'ai_disclosure_check_not_passed' };
    if (BLOCKED_PHONE_JURISDICTIONS.includes(client.jurisdiction)) return { ok: false, reason: 'jurisdiction_requires_ai_disclosure' };
  }
  if (client._invalidJson && client._invalidJson.length) {
    const relevant = { phone: ['Services', 'Opening hours'], quotes: ['Pricing rules'] }[service] || [];
    const bad = client._invalidJson.filter((x) => relevant.includes(x));
    if (bad.length) return { ok: false, reason: `invalid_json_${bad.join('_').replace(/\s/g, '').toLowerCase()}` };
  }
  return { ok: true };
}

// Pick the one client row for a lookup; refuses ambiguous matches (isolation).
function resolveClient(records, { clientId, phoneNumber } = {}) {
  const clients = (records || []).map(normalizeClient);
  let matches = [];
  if (clientId) matches = clients.filter((c) => c.clientId === String(clientId).trim());
  else if (phoneNumber) {
    const p = normalizePhone(phoneNumber);
    matches = clients.filter((c) => c.phone.businessNumber && c.phone.businessNumber === p);
  }
  if (matches.length === 0) return { client: null, error: 'client_not_found' };
  if (matches.length > 1) return { client: null, error: 'ambiguous_client_match' };
  return { client: matches[0], error: null };
}

// Demo/test safety: outbound email to anyone other than Keystone goes to the test inbox.
function safeRecipients(client, emails) {
  const list = (Array.isArray(emails) ? emails : [emails]).filter(Boolean);
  if (!client || client.isDemo) return list.length ? [TEST_INBOX] : [];
  return list;
}

function safeSmsNumber(client, number, testNumber) {
  if (!client || client.isDemo) return testNumber || null;
  return number;
}

// Registry-wide integrity checks: duplicate keys would break isolation.
function validateRegistry(records) {
  const clients = (records || []).map(normalizeClient);
  const problems = [];
  const dup = (key, label) => {
    const seen = {};
    for (const c of clients) {
      const v = key(c);
      if (!v) continue;
      if (seen[v]) problems.push(`Duplicate ${label} "${v}" on ${seen[v]} and ${c.clientName}`);
      else seen[v] = c.clientName;
    }
  };
  dup((c) => c.clientId, 'Client ID');
  dup((c) => c.phone.businessNumber, 'Business phone number');
  dup((c) => c.invoice.xeroTenantId, 'Xero organisation ID');
  dup((c) => c.dashboardToken, 'Dashboard token');
  for (const c of clients) if (!c.clientId) problems.push(`Client "${c.clientName || '(unnamed)'}" has no Client ID`);
  return problems;
}

module.exports = { TEST_INBOX, SERVICE_TOGGLES, BLOCKED_PHONE_JURISDICTIONS, parseJson, splitList, normalizeClient, normalizePhone, gate, resolveClient, safeRecipients, safeSmsNumber, validateRegistry };

  },
  'quotecalc': function (module, exports, require) {
'use strict';
// Custom quote calculator, driven by Airtable "Quote Services" + "Quote Factors" rows
// (per client), plus VAT settings on the client's My Clients row.
// Used by: phone agent (get_quote), the customer quote form, and manual quotes.
// All arithmetic is here; the AI only helps when no service matches.

const r2 = (n) => Math.round((Number(n) + Number.EPSILON) * 100) / 100;
const f = (r) => (r && r.fields ? r.fields : r || {});
const sel = (v) => (v && v.name) || v || '';
const list = (s) => String(s || '').split(/[,;\n]/).map((x) => x.trim()).filter(Boolean);

function loadServices(rows, clientId) {
  return (rows || []).map(f).filter((x) => x['Client ID'] === clientId && x['Active'] !== false && x['Service'])
    .map((x) => ({
      name: x['Service'], basePrice: Number(x['Base price']) || 0, baseCost: Number(x['Cost (base)']) || 0,
      unitName: x['Unit name'] || '', unitPrice: Number(x['Price per unit']) || 0, unitCost: Number(x['Cost per unit']) || 0,
      includedUnits: Number(x['Units included in base']) || 0, keywords: list(x['Keywords']), description: x['Description for customer'] || '',
    }));
}

function loadFactors(rows, clientId) {
  return (rows || []).map(f).filter((x) => x['Client ID'] === clientId && x['Active'] !== false && x['Factor'])
    .map((x) => ({
      name: x['Factor'], type: sel(x['Type']), amount: Number(x['Amount']) || 0, key: (x['Ask as'] || x['Factor']).trim().toLowerCase().replace(/\s+/g, '_'),
      question: x['Question'] || '', applies: sel(x['Applies']) || 'When customer says yes', freeUnits: Number(x['Free units']) || 0,
      onlyFor: list(x['Only for services']).map((s) => s.toLowerCase()), cost: Number(x['Cost']) || 0, waivedIfBooked: !!x['Waived if booked'],
    }));
}

// Pick the service: exact name, then longest keyword/name contained in the description.
function matchService(services, { service, description }) {
  if (service) {
    const s = services.find((x) => x.name.toLowerCase() === String(service).toLowerCase());
    if (s) return s;
  }
  const d = ` ${String(description || service || '').toLowerCase()} `;
  let best = null, len = 0;
  for (const s of services) for (const k of [s.name, ...s.keywords]) {
    const t = k.toLowerCase();
    if (t && d.includes(t) && t.length > len) { best = s; len = t.length; }
  }
  return best;
}

function truthy(v) { return v === true || ['yes', 'true', 'y', '1', 'on'].includes(String(v).toLowerCase()); }

// input: { service?, description?, quantity?, answers: {key: value}, source: 'phone'|'web'|'manual' }
// client: normalised registry row (VAT, margin). Returns a priced quote or {matched:false}.
function calculate({ services, factors, client, input }) {
  const src = input.source || 'web';
  const svc = matchService(services, input);
  if (!svc) return { matched: false, reason: 'no_matching_service', services: services.map((s) => s.name), lines: [], subtotal: 0, vat: 0, total: 0, cost: 0, marginPct: 0, minMarginPct: client.quotes.minMarginPct, belowMarginFloor: false, missing: [], followUps: [], notes: [] };
  const answers = Object.fromEntries(Object.entries(input.answers || {}).map(([k, v]) => [String(k).toLowerCase(), v]));
  const qty = input.quantity !== undefined && input.quantity !== '' ? Number(input.quantity) : (svc.unitName ? null : 0);
  const missing = [];
  if (svc.unitName && (qty === null || isNaN(qty)) && svc.includedUnits === 0) missing.push(`How many ${svc.unitName}s?`);

  const lines = [];
  if (svc.basePrice) lines.push({ description: svc.name, amount: svc.basePrice, cost: svc.baseCost });
  if (svc.unitName && qty) {
    const extra = Math.max(0, qty - svc.includedUnits);
    if (extra > 0) lines.push({ description: `${svc.name}: ${extra} ${svc.unitName}${extra === 1 ? '' : 's'}${svc.includedUnits ? ' extra' : ''} @ £${svc.unitPrice}`, amount: r2(extra * svc.unitPrice), cost: r2(extra * svc.unitCost) });
  }
  const applicable = factors.filter((fc) => !fc.onlyFor.length || fc.onlyFor.includes(svc.name.toLowerCase()));
  const notes = [];
  let multiplier = 1;
  const pctAdjust = [];
  for (const fc of applicable) {
    if (fc.applies === 'Manual quotes only' && src !== 'manual') continue;
    const val = answers[fc.key];
    const on = fc.applies === 'Always' || (fc.applies === 'When customer says yes' && truthy(val)) || ((fc.applies === 'When a number is given' || fc.applies === 'Manual quotes only') && val !== undefined && val !== '' && val !== false);
    if (!on) continue;
    if (fc.type === 'Fixed fee') {
      const waived = fc.waivedIfBooked && truthy(answers.booked);
      lines.push({ description: fc.name + (waived ? ' (waived when you book)' : ''), amount: waived ? 0 : fc.amount, cost: fc.cost });
      if (fc.waivedIfBooked && !waived) notes.push(`${fc.name} is waived if you go ahead and book.`);
    } else if (fc.type === 'Per unit') {
      const n = Math.max(0, Number(val) - fc.freeUnits);
      if (Number(val) > 0 && n > 0) lines.push({ description: `${fc.name} (${n}${fc.freeUnits ? ' beyond first ' + fc.freeUnits : ''})`, amount: r2(n * fc.amount), cost: r2(Number(val) * fc.cost) });
    } else if (fc.type === 'Materials markup %') {
      const m = Number(val) || 0;
      if (m > 0) lines.push({ description: fc.name, amount: r2(m * (1 + fc.amount / 100)), cost: m });
    } else if (fc.type === 'Multiplier') { multiplier *= fc.amount || 1; pctAdjust.push({ name: fc.name, mult: fc.amount }); }
    else if (fc.type === 'Percent of job') pctAdjust.push({ name: fc.name, pct: fc.amount });
  }
  // Multipliers and % apply to the service part of the job only (not travel/materials/fixed fees).
  const serviceTotal = lines.filter((l) => l.description.startsWith(svc.name)).reduce((s, l) => s + l.amount, 0);
  for (const p of pctAdjust) {
    const amt = p.mult !== undefined ? r2(serviceTotal * (p.mult - 1)) : r2(serviceTotal * p.pct / 100);
    if (amt) lines.push({ description: p.name, amount: amt, cost: 0 });
  }
  if (input.discountPct && src === 'manual') lines.push({ description: `Discount (${input.discountPct}%)`, amount: -r2(lines.reduce((s, l) => s + l.amount, 0) * input.discountPct / 100), cost: 0 });

  const vatRate = client.invoice.vatRatePct === undefined ? 20 : client.invoice.vatRatePct;
  const inc = !!client.quotes.pricesIncludeVat;
  const gross = r2(lines.reduce((s, l) => s + l.amount, 0));
  const subtotal = inc ? r2(gross / (1 + vatRate / 100)) : gross;
  const vat = inc ? r2(gross - subtotal) : r2(subtotal * vatRate / 100);
  const total = inc ? gross : r2(subtotal + vat);
  const cost = r2(lines.reduce((s, l) => s + (l.cost || 0), 0));
  const marginPct = subtotal > 0 ? r2((subtotal - cost) / subtotal * 100) : 0;
  const followUps = applicable.filter((fc) => fc.applies !== 'Always' && fc.applies !== 'Manual quotes only' && answers[fc.key] === undefined && fc.question).map((fc) => fc.question);
  return {
    matched: true, service: svc.name, serviceDescription: svc.description, lines: lines.map((l) => ({ ...l, amount: r2(l.amount), cost: r2(l.cost || 0) })),
    subtotal, vat, vatRate, pricesIncludeVat: inc, total, cost, marginPct, minMarginPct: client.quotes.minMarginPct,
    belowMarginFloor: subtotal > 0 && marginPct < client.quotes.minMarginPct, missing, followUps, notes,
  };
}

// The phrase the phone agent reads out. Always says "estimate".
function phoneSentence(q, clientName) {
  if (!q.matched) return `I can't give a set price for that over the phone, but I'll pass the details to the ${clientName} team and they'll get back to you with a quote.`;
  if (q.missing.length) return `To work out a price I just need to know: ${q.missing.join(' ')}`;
  const price = `£${Math.round(q.total)}`;
  return `For a ${q.service.toLowerCase()} the estimate is about ${price} including VAT. That's an estimate, and the team will confirm the final price.${q.notes.length ? ' ' + q.notes.join(' ') : ''}`;
}

const AI_QUOTE_SYSTEM = `You help a UK small business price a job its standard price list does not cover.
Use ONLY the business's own services and rates provided. Propose net (ex-VAT) line items with your estimated cost per line.
Do not calculate VAT or totals. If you cannot price it sensibly, return no lines and up to 3 short questions.
This is a draft the business owner will check before anything reaches the customer.`;

function aiQuotePrompt({ client, services, factors, input }) {
  return `Business: ${client.clientName} (${client.industry})
Customer request: ${input.description || input.service}
Answers given: ${JSON.stringify(input.answers || {})}
Price list (services): ${JSON.stringify(services.map((s) => ({ name: s.name, base: s.basePrice, unit: s.unitName, perUnit: s.unitPrice, cost: s.baseCost, unitCost: s.unitCost })))}
Pricing factors: ${JSON.stringify(factors.map((x) => ({ name: x.name, type: x.type, amount: x.amount })))}
Minimum margin: ${client.quotes.minMarginPct}%`;
}

const AI_QUOTE_SCHEMA = {
  type: 'object', additionalProperties: false, required: ['lines', 'questions', 'reasoning', 'confidence'],
  properties: {
    lines: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['description', 'amount', 'cost'], properties: { description: { type: 'string' }, amount: { type: 'number' }, cost: { type: 'number' } } } },
    questions: { type: 'array', items: { type: 'string' } },
    reasoning: { type: 'string' },
    confidence: { type: 'number' },
  },
};

// Totals for AI-proposed lines (same VAT / margin rules).
function totalsFromLines(lines, client) {
  const vatRate = client.invoice.vatRatePct === undefined ? 20 : client.invoice.vatRatePct;
  const subtotal = r2(lines.reduce((s, l) => s + (Number(l.amount) || 0), 0));
  const vat = r2(subtotal * vatRate / 100);
  const cost = r2(lines.reduce((s, l) => s + (Number(l.cost) || 0), 0));
  const marginPct = subtotal > 0 ? r2((subtotal - cost) / subtotal * 100) : 0;
  return { subtotal, vat, vatRate, total: r2(subtotal + vat), cost, marginPct, minMarginPct: client.quotes.minMarginPct, belowMarginFloor: subtotal > 0 && marginPct < client.quotes.minMarginPct };
}

module.exports = { loadServices, loadFactors, matchService, calculate, phoneSentence, AI_QUOTE_SYSTEM, aiQuotePrompt, AI_QUOTE_SCHEMA, totalsFromLines, truthy, r2 };

  },
  'quotehtml': function (module, exports, require) {
'use strict';
// Branded quote email (print-friendly, so it can be saved as PDF from any email app)
// and the customer-facing quote form page.

const { escapeHtml: e } = require('./log');
const { shell, table, gbp } = require('./render');

function linesTable(q) {
  const rows = q.lines.map((l) => [e(l.description), gbp(l.amount)]);
  if (q.pricesIncludeVat) rows.push(['<strong>Total (inc VAT)</strong>', `<strong>${gbp(q.total)}</strong>`], [`<span style="color:#6b7280">Includes VAT at ${q.vatRate}%</span>`, `<span style="color:#6b7280">${gbp(q.vat)}</span>`]);
  else rows.push(['Subtotal', gbp(q.subtotal)], [`VAT (${q.vatRate}%)`, gbp(q.vat)], ['<strong>Total</strong>', `<strong>${gbp(q.total)}</strong>`]);
  return table(rows, ['Item', 'Price']);
}

// To the CUSTOMER (after approval, or directly for manual quotes).
function customerQuoteEmail(client, q) {
  const body = `<h2 style="margin-top:0">Your quote ${e(q.ref)}</h2>
<p>Hi ${e(q.customerName || 'there')},</p>
<p>Thanks for getting in touch with ${e(client.clientName)}. Here is your quote for <strong>${e(q.service || q.description)}</strong>.</p>
${q.serviceDescription ? `<p style="color:#4b5563">${e(q.serviceDescription)}</p>` : ''}
${linesTable(q)}
${(q.notes || []).length ? `<p>${q.notes.map(e).join('<br>')}</p>` : ''}
<p style="font-size:13px;color:#4b5563">Valid until ${e(q.validUntil)}. ${q.pricedBy === 'agent' ? 'This is an estimate based on the details provided; we will confirm on site. ' : ''}Reply to this email to book or ask a question.</p>`;
  return shell(client, `Quote ${q.ref} from ${client.clientName}`, body);
}

// To the BUSINESS for approval (form and phone quotes).
function approvalEmail(client, q, approveUrl) {
  const flag = q.belowMarginFloor
    ? `<p style="background:#fee2e2;border-left:4px solid #dc2626;padding:10px"><strong>Below your minimum margin:</strong> ${q.marginPct}% vs ${q.minMarginPct}%. Check the price before approving.</p>`
    : `<p style="color:#059669;font-size:13px">Estimated margin ${q.marginPct}% (your minimum ${q.minMarginPct}%).</p>`;
  const body = `<h2 style="margin-top:0">${q.total > 0 ? 'New quote to approve' : 'Quote request needs details'}: ${e(q.ref)}</h2>
<p><strong>${e(q.customerName || 'Customer')}</strong> ${q.customerEmail ? '(' + e(q.customerEmail) + ')' : ''} ${q.customerPhone ? e(q.customerPhone) : ''} asked for: ${e(q.description || q.service)}</p>
<p>Source: ${e(q.source)} · Priced by: ${q.pricedBy === 'agent' ? 'AI estimate (not in your price list)' : 'your price list'}</p>
${linesTable(q)}
${flag}
${q.agentNotes ? `<p style="font-size:13px"><strong>How the AI priced it:</strong> ${e(q.agentNotes)}</p>` : ''}
${(q.questions || []).length ? `<p><strong>Still need from the customer:</strong></p><ul>${q.questions.map((x) => `<li>${e(x)}</li>`).join('')}</ul>` : ''}
${approveUrl && q.customerEmail && !(q.questions || []).length ? `<p><a href="${e(approveUrl)}" style="background:#059669;color:#fff;padding:12px 18px;border-radius:6px;text-decoration:none;display:inline-block">Approve and send to customer</a></p><p style="font-size:12px;color:#6b7280">Want to change it? Edit the quote in Airtable (Quotes table) and create a manual quote instead.</p>` : '<p>No email address or details still needed, so call the customer to finish this one.</p>'}
<p style="font-size:12px;color:#6b7280">Nothing has been sent to the customer yet.</p>`;
  return shell(client, `Approve quote ${q.ref}`, body);
}

function page(client, title, inner) {
  const colour = /^#[0-9a-f]{3,8}$/i.test(client.invoice.brandColour) ? client.invoice.brandColour : '#1F3A5F';
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${e(title)}</title>
<style>body{margin:0;background:#f4f5f7;font-family:-apple-system,Segoe UI,Helvetica,Arial,sans-serif;color:#1d2433}
.wrap{max-width:620px;margin:0 auto;padding:16px}.head{background:${colour};color:#fff;padding:18px 20px;border-radius:10px 10px 0 0;font-size:20px;font-weight:600}
.card{background:#fff;padding:20px;border-radius:0 0 10px 10px}label{display:block;font-weight:600;margin:14px 0 6px;font-size:14px}
input,select,textarea{width:100%;box-sizing:border-box;padding:10px;border:1px solid #d0d5dd;border-radius:6px;font-size:15px;font-family:inherit}
.check{display:flex;gap:8px;align-items:center;font-weight:400}.check input{width:auto}
