  { id: 'invoices_per_month', pillar: 'invoicing', q: 'Invoices sent per month', type: 'number' },
  { id: 'days_to_invoice', pillar: 'invoicing', q: 'Days from job finished to invoice sent (typical)', type: 'number' },
