  { id: 'kpis_tracked', pillar: 'reporting', q: 'Which numbers do you track weekly? (comma list)', type: 'text' },
  { id: 'admin_hours_reporting_month', pillar: 'reporting', q: 'Hours per month pulling numbers together', type: 'number' },
