function roundTo(v, u) { return Math.round(v / u) * u; }

function computeRange(base, mults, { floorPct = 0.7, ceilPct = 2.0, midUnit = 50 } = {}) {
  const mult = mults.reduce((a, b) => a * (b || 1), 1);
